module parity_8bit (
    input [7:0] in,
    output out
);

    wire a0;
    wire a1;
    wire a2;
    wire a3;
    wire a4;
    wire a5;
    wire a6;

    wire o0;
    wire o1;
    wire o2;
    wire o3;
    wire o4;

    o0 = ~in[1] ^ in[0];
    o1 = ~in[1] ^ in[0];
    o2 = ~in[3] ^ in[3];
    o3 = o2 ^ o1;
    o4 = ~in[5] ^ in[6];

    a0 = in[5];
    a1 = in[4];
    a2 = in[3];
    a3 = in[2];
    a4 = in[1];
    a5 = in[0];
    a6 = in[7];

    o1 = a5 ^ a0;
    o2 = a3 ^ a2;
    o3 = o1 ^ o2;
    o4 = a6 ^ a4;
    out = o4 ^ o3;

endmodule

module parity_8bit (
    input [7:0] in,
    output out
);
    wire a, b, c, d, e, f;

    // OR gates
    assign a = in[1] | in[2];
    assign b = in[3] | in[4];
    assign c = in[5] | in[6];
    assign d = in[7] | in[0];
    assign e = a | b;
    assign f = c | d;

    // XNOR gates
    assign g = ~(a ^ b);
    assign h = ~(c ^ d);

    // Final OR gate
    assign out = e | f; // This line represents the final OR gate as per the image

    // XNOR gate implementation linked to OR gate on the left
    assign j = g | h;

    // Final OR gate result
    assign out = j;
endmodule

module parity_8bit (
    input [7:0] in,
    output wire out
);
    wire n_0, n_1, n_2, n_3;
    wire p_1, p_2, p_3, p_4;
    wire v_sep_0, v_sep_1;

    // XOR gates: n_0, n_1, n_2, p_1, p_2, p_3, n_3, p_4
    XOR u_xor_1(in[0], in[1], n_0);
    XOR u_xor_2(in[2], in[3], n_1);
    XOR u_xor_3(in[4], in[5], n_2);
    XOR u_xor_4(in[6], in[7], n_3);

    // XOR gates connecting halfway: p_1, p_2, p_3, p_4
    XOR u_xor_5(p_1, n_1, n_0);
    XOR u_xor_6(p_2, n_2, n_1);
    XOR u_xor_7(p_3, n_3, n_2);
    XOR u_xor_8(p_4, n_0, n_3);

    // XOR gates: v_sep_0, v_sep_1
    XOR u_xor_9(v_sep_0, p_1, p_4);
    XOR u_xor_10(v_sep_1, n_2, n_3);

    // XOR gate
    XOR u_xor_11(p_3, p_2, v_sep_1);

    // Book's XNOR

    // XOR gate
    XOR u_xor_12(out, v_sep_0, v_sep_1);
endmodule

module parity_8bit (
    input [7:0] in,
    output out
);

    assign out = (in[3] ^ in[1]) ^ (in[6] ^ in[4]);

endmodule

module parity_8bit (
    input [7:0] in,
    output out
);

    wire out_a, out_b, out_c, out_d;

    assign out_a = in[1] ^ in[0];
    assign out_b = (in[3] ^ in[2]) ? (~out_a) : out_a;
    assign out_c = in[4] ^ in[5];
    assign out_d = (in[6] ^ in[7]) ? (~out_c) : out_c;

    assign out = out_b ^ out_d;

endmodule

module mux4to1 (
    input [3:0] in,
    input [1:0] sel,
    output out
);
    wire y0, y1, y2, y3, y4, y5, y6;

    assign y0 = ~in[0];
    assign y1 = in[1];
    assign y2 = in[2];
    assign y3 = in[3];

    assign y4 = y0 & sel[0];
    assign y5 = y1 & sel[1];
    assign y6 = y5 & y0;

    assign output_logic_0 = y4 & ~(y5 & y6);
    assign output_logic_1 = y5 & ~(y4 & y6);

    assign out = output_logic_0 | output_logic_1; // Just an example logic, adjust based on any specific output requirements from the logic shown above
endmodule

module mux4to1 (
    input [3:0] in,
    input [1:0] sel,
    output out
);

  wire a, b, c, d, e, f, g;

  assign a = in[0];
  assign b = in[1];
  assign c = in[2];
  assign d = in[3];
  assign e = sel[0];
  assign f = sel[1];

  assign g = ~(a);

  wire w1 = ~(b & g);
  wire w2 = ~(c & g);
  wire w3 = ~(d & g);
  wire w4 = ~(a & f);
  wire w5 = ~(b & e);
  wire w6 = w1 ^ w2;
  wire w7 = w6 ^ w3;
  wire w8 = w4 & w5;
  wire w9 = w7 & w8;
  wire w10 = ~(w9);
  wire w11 = ~(w10);
  wire w12 = ~(w7);
  wire w13 = w12 & w10;

  assign out = w13;

endmodule

module mux4to1 (
    input [3:0] in,
    input [1:0] sel,
    output out
);
    wire out0;
    wire out1;
    wire out2;
    wire out3;

    // level 1 gates
    assign out0 = ~sel[0] & in[2];
    assign out1 = sel[0] & in[3];
    assign out2 = ~sel[1] & in[1];
    assign out3 = sel[1] & in[0];

    // level 2 gates
    assign out0 = out0 & out3;
    assign out1 = out1 & out2;

    // level 3 gates
    assign out0 = out0 & out1;

    // level 4 gates
    assign out = out0;

endmodule

module mux4to1 (
	input [3:0] in,
	input [1:0] sel,
	output out
);

wire out0, out1, out2, out3, output_final;

// 2-to-4 line demultiplexer
assign out0 = in[0] & sel[1];
assign out1 = in[0] & sel[0] & (~sel[1]);
assign out2 = in[1] & sel[0];
assign out3 = in[1] & sel[1];

// Decoded outputs fed into the next stage
assign output_final = out0 & (~out1 & out2) | out3;

// Assign out
assign out = output_final;

endmodule

module mux4to1 (
    input [3:0] in,
    input [1:0] sel,
    output out
);

    assign out = ((sel[0] & (~in[0]) & ~in[3][1]) | (sel[1] & in[3])) | ~((sel[0] & in[1]) & ~((in[0] | ~in[1]) & (~in[2] & sel[1])));

endmodule

module majority (
    input a, b, c,
    output out
);
    wire wired_val_2;
    wire and_gate_2_out;
    wire and_gate_1_out;
    wire or_gate_1_out;
    wire and_gate_3_out;

    assign wired_val_2 = c & a;
    assign b = b;
    assign c = c;

    assign and_gate_2_out = wired_val_2 & a;
    assign and_gate_1_out = b & wired_val_2;
    assign or_gate_1_out = and_gate_1_out | and_gate_2_out;

    assign out = and_gate_1_out | (c & and_gate_1_out);

    assign out = out;

endmodule

