module majority (
    input a, b, c,
    output out
);
    wire a, b, c, d, e, f;

    // Second level of AND gates
    assign a = &{a, b};
    assign b = &{a, b, c};
    assign c = &{a, b, c};

    // First level of AND gates
    assign d = a[0] | c[0];
    assign e = a[1] | b[0];
    assign f = c[1] | c;

    // Final OR gate
    assign out = d | e | f;
endmodule

