module bin_to_gray (
    input [3:0] binary,
    output [3:0] gray
);

assign gray[3] = binary[3] ^ binary[0];
assign gray[2] = binary[3] ^ binary[1];
assign gray[1] = binary[3] ^ binary[2];
assign gray[0] = binary[2] ^ binary[0];

endmodule

module bin_to_gray (
    input [3:0] binary,
    output [3:0] gray
);

    assign gray[0] = (~binary[3] || binary[2]);
    assign gray[1] = (~binary[3] || binary[0]);
    assign gray[2] = (~binary[2] || binary[0]);
    assign gray[3] = (~binary[0] || binary[2]);

