module bin_to_gray (
    input [3:0] binary,
    output [3:0] gray
);
    wire s0, s1, s2, s3, s4, s5, s6, s7;
    assign s0 = binary[0] | binary[1];
    assign s1 = binary[1] | binary[0];
    assign s2 = binary[2] | binary[0];
    assign s3 = binary[0] | binary[2];
    assign s4 = binary[3] | binary[1];
    assign s5 = binary[1] | binary[3];
    assign s6 = binary[2] | binary[3];
    assign s7 = binary[3] | binary[2];

    assign gray[0] = s0 | s1;
    assign gray[1] = s1 | s2;
    assign gray[2] = s2 | s3;
    assign gray[3] = s3 | s7;

endmodule

module eq_comparator (
    input [3:0] a,
    input [3:0] b,
    output equal
);

    wire or_1_out;   // Output of OR with inputs b[0], a[0]
    wire nor_1_out;  // Output of NOR with inputs b[0], a[0]

    wire and_1_out;   // Output of AND with inputs b[0], a[1]
    wire nor_2_out;   // Output of NOR with inputs b[1], a[1]

    wire and_2_out;   // Output of AND with inputs b[1], a[2]
    wire xor_1_out;   // Output of XOR with inputs b[2], a[2]

    wire or_2_out;    // Output of OR with inputs b[2], a[2]

    wire or_3_out;    // Output of OR with inputs b[3], a[3]
    wire nor_3_out;   // Output of NOR with inputs b[3], a[3]

    wire nor_4_out;   // Output of NOR with inputs b[0], nor_3_out
    wire or_4_out;    // Output of OR with inputs a[2], nor_1_out

    // OR gate: b[0] OR a[0] -> or_1_out
    assign or_1_out = b[0] | a[0];
    // NO-OR gate: NOR(b[0], a[0]) -> nor_1_out
    assign nor_1_out = !(b[0] | a[0]);
    // AND gate: b[0] AND a[1] -> and_1_out
    assign and_1_out = b[0] & a[1];
    // NOR gate: NOR(b[1], a[1]) -> nor_2_out
    assign nor_2_out = !(b[1] | a[1]);
    // AND gate: b[1] AND a[2] -> and_2_out
    assign and_2_out = b[1] & a[2];
    // XOR gate: b[2] XOR a[2] -> xor_1_out
    assign xor_1_out = b[2] ^ a[2];
    // OR gate: b[2] OR a[2] -> or_2_out
    assign or_2_out = b[2] | a[2];
    // OR gate: b[3] OR a[3] -> or_3_out
    assign or_3_out = b[3] | a[3];
    // NOR gate: NOR(b[3], a[3]) -> nor_3_out
    assign nor_3_out = !(b[3] | a[3]);
    // NOR gate: NOR(b[0], a[3]) -> nor_4_out
    assign nor_4_out = !(b[0] | a[3]);
    // OR gate: a[2] OR nor_1_out -> or_4_out
    assign or_4_out = a[2] | nor_1_out;

    // AND gate: b[0] AND a[2]
    assign equal[0] = b[0] & a[2];
    // AND gate: a[0] AND b[3]
    assign equal[1] = a[0] & b[3];
    // XOR gate: a[2] XOR a[3]
    assign equal[2] = a[2] ^ a[3];
    // OR gate: a[3] OR b[3] NOR(or_1_out, a[2])
    assign equal[3] = a[3] | (a[2] | or_3_out) | (~nor_2_out);

    // OR gate with inputs a[2], a[3] -> or_2_out
    assign or_2_out = a[2] | a[3];

endmodule

module eq_comparator (
    input [3:0] a,
    input [3:0] b,
    output equal
);

    wire y0, y1, y2, y3;
    wire y4, y5, y6, y7;

    // First level: XOR gates with scan 6
    always @(*) begin
        y0 = b[0] ^ a[0];
        y1 = b[0] ^ a[1];
        y2 = b[2] ^ a[2];
        y3 = b[1] ^ a[3];
        y4 = b[0] ^ a[3];
        y5 = b[2] ^ a[1];
        y6 = b[1] ^ a[2];
    end

    // Second level: XOR gates with scan 3
    always @(*) begin
        y4 = y0 ^ y3;
        y5 = y1 ^ y3;
        y6 = y2 ^ y4;
    end

    // Third level: NAND gate
    always @(*) begin
        wire nand_out;
        nand_out = !(y6 & a[1]);
        y4 = nand_out;
    end

    // Fourth level: NAND gate
    always @(*) begin
        wire nand_out;
        nand_out = !(y4 & a[0]);
        y2 = nand_out;
    end

    // Fifth level: OR gate
    always @(*) begin
        y2 = y2 | y0;
    end

    // Output assignment
    assign equal = y2;

endmodule

module eq_comparator (
    input [3:0] a,
    input [3:0] b,
    output equal
);

    wire n_0, n_1, n_2, n_3; // Intermediate XNOR outputs for b
    wire n_4, n_5, n_6, n_7; // Intermediate XNOR outputs for a
    wire sum_or AND_path, sum_or AND_path; // Intermediate OR/AND gate outputs

    // Level 1: Part 1 (3 XNOR gates)
    n_0 = ~(b[0] ^ b[1]);
    n_1 = ~(b[1] ^ b[2]);
    n_2 = ~(b[2] ^ b[3]);

    // Level 2: Part 2 (3 XNOR gates)
    n_4 = ~(a[0] ^ a[1]);
    n_5 = ~(a[1] ^ a[2]);
    n_6 = ~(a[2] ^ a[3]);

    // Level 3: Part 3 (Merging and addition)
    sum_or AND_path = ~(n_0 & n_2);
    sum_or AND_path = n_6 | n_2;

    // Level 4: Final Output (one XNOR gate)
    equal = ~(sum_or AND_path & sum_or AND_path);

endmodule

module eq_comparator (
    input [3:0] a,
    input [3:0] b,
    output equal
);

    wire sig_1_0, sig_1_1, sig_1_2, sig_1_3; // Intermediate XNOR outputs
    wire sig_2_0, sig_2_1, sig_2_2, sig_2_3; // Intermediate XNOR outputs

    // Generate outputs of XNOR gates
    sig_1_0 = ~(b[0] ^ b[1]);
    sig_1_1 = ~(b[1] ^ b[2]);
    sig_1_2 = ~(b[2] ^ b[3]);
    sig_1_3 = ~(b[3] ^ b[0]);
    sig_2_0 = ~(a[0] ^ a[1]);
    sig_2_1 = ~(a[1] ^ a[2]);
    sig_2_2 = ~(a[2] ^ a[3]);
    sig_2_3 = ~(a[3] ^ a[0]);

    // Generate outputs of the AND and OR gates
    wire AND_path = sig_1_0 & sig_1_2;
    wire OR_path = sig_2_2 | sig_2_3;
    wire OR1_path = AND_path & OR_path;
    wire OR2_path = ~(OR1_path);

    // Final XOR gate output
    equal = ~(sig_1_3 ^ OR2_path);

endmodule

module eq_comparator (
    input [3:0] a,
    input [3:0] b,
    output equal
);
    wire y0, y1, y2, y3;
    wire y0_n, y1_n, y2_n, y3_n;
    wire y0n_1_n, y0n_2_n;
    wire y1n_3_n, y1n_4_n;
    wire y2n_5_n, y2n_6_n;
    wire y2n_7_n, y2n_8_n;
    wire final_1, final_2;

    always @(*) begin
        // Row 0
        y0 = (~b[0] & a[0]);
        y0_n = (~y0 & 1'b1);
        y0n_1_n = ~(y0_n & b[1]);
        y0n_2_n = ~(a[1] & y0n_1_n);

        // Row 1
        y1 = (~b[1] & a[1]);
        y1_n = (~y1 & 1'b1);
        y1n_3_n = ~(y1_n & b[2]);
        y1n_4_n = ~(a[2] & y1n_3_n);

        // Row 2
        y2 = (~b[2] & a[2]);
        y2_n = (~y2 & 1'b1);
        y2n_5_n = ~(y2_n & b[3]);
        y2n_6_n = ~(a[3] & y2n_5_n);
        y2n_7_n = y2n_6_n;
        y2n_8_n = y0n_2_n;

        // Row 3
        y3 = (~a[0] & b[0]);
        y3_n = (~y3 & 1'b1);
        y1n_4_n = y1n_3_n;
    end

    // Final Logic Construction
    final_1 = ~(a[0] & b[0]);
    final_2 = ~(a[0] & b[1]);

    equal = final_1 & final_2;
endmodule

module eq_comparator (
    input [3:0] a,
    input [3:0] b,
    output equal
);

    wire x0, x1, x2, x3, y0, y1, y2, y3, z0, z1, z2, z3;

    // Layer 1: XNOR gates from a and b
    x0 = ~(a[3] ^ b[3]);
    x1 = ~(a[2] ^ b[2]);
    x2 = ~(a[1] ^ b[1]);
    x3 = ~(a[0] ^ b[0]);

    // First level OR gate outputs (combined with x0, x1)
    y0 = x0 | x2;
    y1 = x1 | x3;

    // Second level OR gate outputs (output of first layer OR gates)
    z0 = y0 | y1;
    z1 = y0;
    z2 = y1;
    z3 = z2;

    // Next layer of OR gates
    wire w0, w1, w2, w3;
    w0 = z0 | x0;
    w1 = z0 | y0;
    w2 = z0 | z2;
    w3 = z1 | z2;

    // Final layer of OR gates
    wire out = w2 | w3;

    assign equal = out;
endmodule

module decoder_2to4 (
    input [1:0] in,
    output [3:0] out
);

    output reg [3:0] out;
    reg [3:0] val_0_s;

    always @(in[0] or in[1] or out[2:0]) begin
        if (in[0])
            val_0_s = {3{1'b0}, in[1]};
        else
            val_0_s = in;
        out = val_0_s;
    end

endmodule

module decoder_2to4 (
    input [1:0] in,
    output [3:0] out
);
    wire a, b, c, d, e, f, g;
    wire [1:0] temp_sel_0, temp_sel_1;

    // First 2-input NAND gates
    assign a = not(in[0]);
    assign b = not(in[1]);
    assign c = not(in[0] & in[1]);

    // Second 2-input NAND gates (output of first layer)
    assign d = not(a & in[0]);
    assign e = not(b & in[1]);
    assign f = not(c & in[0] & in[1]);

    // 4-input NAND gate output
    assign g = not(a & b & c & d & e & f);

    // Assign out based on input select lines (implied to be constant high for this logic:)
    // Assuming in[1] is the higher order, which would route one of these outputs to out[0] etc.
    // The direct mapping would be g to all 4 bits since no reselting data is shown.
    // But based on the arrow structure from in -> 2x input gate -> 4x output gate:
    // Let's assume the DAG shows in routing to the first layer, then to second layer.

    assign out[0] = (in[1] | in[0]); // OR output commonly seen in multiplexers if input
    assign out[1] = g;
    assign out[2] = g;
    assign out[3] = g;

endmodule

module decoder_2to4 (
    input [1:0] in,
    output [3:0] out
);

    // Define the bits of in and out based on the diagram
    assign out[0] = !(!in[1] & in[0]); // out[0] = XNOR(in[1], in[0])
    assign out[1] = (!in[1] & !in[0]); // out[1] = ... 
    assign out[2] = (!in[0]); // out[2] = NOT(in[0])
    assign out[3] = (!in[1] & !in[0]); // out[3] = ...

endmodule

module decoder_2to4 (
    input [1:0] in,
    output [3:0] out
);
    reg val_1_a, val_1_b, val_1_c, val_1_d;
    wire in_line1_top, in_line2_top, in_line3_top, in_line4_top;

    // NOR Gates
    nor_gate(in_line1_top, in[0], out[0], out[0]);
    nor_gate(in_line2_top, in[0], out, out, out);
    nor_gate(in_line3_top, in[1], val_1_a, val_1_b, val_1_a);
    nor_gate(in_line4_top, in[1], out, val_1_c, val_1_d);

    // NAND Gates
    // LESM1 with in, in_line3_top, in_line4_top
    nand_1_in(out[0], in[1], in_line3_top, in_line4_top, in_line3_top, in[0], val_1_a, out[0]);
    // LESM2 with out[0], in_line3_top, in_line4_top, in_line1_top
    nand_1_in(out[1], out[0], in_line3_top, in_line4_top, in_line3_top, in_line4_top, in_line1_top, val_1_b, out[1]);
    // LESS1 with out[1], in_line3_top, in_line4_top, in_line1_top
    nand_1_in(out[2], out[1], in_line3_top, in_line4_top, in_line3_top, in_line4_top, in_line1_top, val_1_c, out[2]);
    // LESS2 with out[2]
    nand_1_in(out[3], out[2], out[2], out[2], in_line1_top, in[1], val_1_d, out[3]);
endmodule

