  wire b[2][4];   // Second layer of logic
  wire c[3][4];   // Third layer of logic
  wire d[4][4];   // Fourth layer of logic
  wire e[5][4];   // Fifth layer of logic
  wire f[6][4];   // Sixth layer of logic
  wire g[7:0];    // Final outputs

begin
  // First layer of logic
  for (int i = 0; i < 4; i++) {
    a[0][i] = (b[8 - i] | a[8 - i]) ? 0 : 1;
    a[1][i] = (a[i] | b[i]) ? 0 : 1;
    a[2][i] = (a[i] | a[i]) ? 0 : 1;
    a[3][i] = (a[i] | b[i+1]) ? 0 : 1;
  }

  // Second layer of logic
  for (int i = 0; i < 4; i++) {
    b[0][i] = a[0][i] | a[1][i];
    b[1][i] = a[2][i] | a[3][i];
    b[2][i] = a[1][i] | a[3][i];
    b[3][i] = a[0][i] | a[2][i];
  }

  // Third layer of logic
  for (int i = 0; i < 4; i++) {
    c[0][i] = b[0][i] | b[1][i];
    c[1][i] = b[2][i] | b[3][i];
    c[2][i] = b[1][i] | b[3][i];
    c[3][i] = b[0][i] | b[2][i];
  }

  // Fourth layer of logic
  for (int i = 0; i < 4; i++) {
    d[0][i] = c[0][i] | c[1][i];
    d[1][i] = c[2][i] | c[3][i];
    d[2][i] = c[1][i] | c[3][i];
    d[3][i] = c[0][i] | c[2][i];
  }

  // Fifth layer of logic
  for (int i = 0; i < 4; i++) {
    e[0][i] = d[0][i] | d[1][i];
    e[1][i] = d[2][i] | d[3][i];
    e[2][i] = d[1][i] | d[3][i];
    e[3][i] = d[0][i] | d[2][i];
  }

  // Sixth layer of logic
  for (int i = 0; i < 4; i++) {
    f[0][i] = e[0][i] | e[1][i];
    f[1][i] = e[2][i] | e[3][i];
    f[2][i] = e[1][i] | e[3][i];
    f[3][i] = e[0][i] | e[2][i];
  }

  // Final outputs
  for (int i = 0; i < 8; i++) {
    g[i] = f[4-i] & f[4-i-1];
  }

  // Final output assignment
  assign s = g;
  assign overflow = f[4];
end

endmodule

