module TopModule (
  input [31:0] in,
  output [31:0] out
);
  // The circuit swaps the following segments of 32-bit in
  // and assigns them to corresponding segments in out.
  // Lower 8 bits: remains same
  // Next 16 bits (8:15): swapped with 16:23
  // Next 16 bits (24:31): swapped with 8:15
  // The output is computed directly.
  out[0:7]       = in[0:7];
  out[8:15]       = in[16:23];
  out[16:23]      = in[8:15];
  out[24:31]      = in[24:31];
endmodule

module TopModule (
  input [4:0] a,
