  input [4:0] f,
  output [7:0] w,
  output [7:0] x,
  output [7:0] y,
  output [7:0] z
);
  wire zero = 1'd0;
  wire [7:0] temp1;
  wire [1:0] pattern1;
  wire [7:0] temp2;
  wire [7:0] temp3;
  wire val_6_wire;
  wire [1:0] pattern2;
  wire [7:0] temp4;

pattern1 <= 2'b10; // D0: 0000
pattern1[0] <= 1'b1;

pattern2 <= 2'b01; // D0: 0000
pattern2[0] <= 1'b0;

  assign temp1[7:0] = x[7:0] + z[7:0]; 
  assign y[7:0] = temp1[7:0] + w[7:0]; 
  assign w[7:0] = temp1[7:0] + x[7:0]; 

  assign f[4:0] = f[7:0] * (e[7:0] & zero); 
  assign e[7:0] = f[4:0]; 
  assign c[7:0] = (d[7:0] == 1'b0) ? zero : temp2[7:0]; 
  assign d[7:0] = temp2[7:0]; 
  assign temp2[7:0] = (b[7:0] & (b[7:0] & (c[7:0] & pattern1[7:0]))) ? 8'd0 : temp3[7:0]; 
  assign temp3[7:0] = (a[7:0] <= 1'b0) ? 0 : temp4[7:0]; 
  assign temp4[7:0] = (a[7:0] >= 1'b0) ? 0 : a[7:0]; 

  assign w[7:0] = (val_6_wire[7:0] >= 1) ? f[4:0] : zero; 

  assign c[4:0] = (b[7:0] == 1'b0) ? a[7:0] : a[4:0];
  assign b[7:0] = (b[7:0] & pattern1) ? b[7:0] & pattern1 : b[7:0] + b[4:0];

endmodule

