  a               -> w[1];
  a               -> w[2];
  a               -> w[3];
  a               -> w[4];
  a               -> w[5];

  /* b -> x */
  /* b -> x[2:4] (LSB of MSB of x) */
  b               -> x[2];
  b               -> x[3];
  b                -> x[4];

  /* c -> omitted (no connections from c in diagram for w) */

  /* Connecting w1 and w2 */
  w1                  -> w[6];
  w1                  -> w[7];

  /* Connecting w2 and d[6:0] to y [1:7] */
  w2[0]               -> y[7];
  w2[1]               -> y[6];
  w2[2]               -> y[5];
  w3[0]               -> y[4];
  w3[1]               -> y[3];
  w3[2]               -> y[2];
  w3[3]               -> y[1];

  /* Connecting w3 to x[6:7] */
  w3[0]               -> x[6];
  w3[1]               -> x[7];

  /* Connecting e[0] to w6[0], then w6[1:6] based on input b... */
  e[0]            -> w6[0];

  /* c[0] -> w[6], c[1] -> w[7] */
  c[0]            -> w[6];
  c[1]            -> w[7];
endmodule

