module TopModule (
  input [2:0] a,
  input [2:0] b,
  output [2:0] out_or_bitwise,
  output out_or_logical,
  output [5:0] out_not
);
    wire w17_n, w15_n, w14_n, w19_n, w16_n, w13_n, w12_n, w11_n, w10_n, w4_n;
    wire a, B, C, D, E, F, G, H;

    // Decoders for a and b
    always @(*) begin
        if(a == 3'b000) begin
            a <= 1; B; C; D <= 0; E; F; G; H <= 0;
        end else if(a == 3'b001) begin
            A; B; C <= 1; D; E <= 0; F; G; H <= 0;
        end else if(a == 3'b010) begin
            A; B; C <= 0; D; E <= 0; F; G; H <= 1;
        end else if(a == 3'b011) begin
            A; B; C; D <= 1; E; F <= 0; G; H <= 0;
        end else if(a == 3'b100) begin
            A; B; C; D <= 1; E; F; G <= 0; H;
        end else if(a == 3'b101) begin
            A; B; C; D; E; F <= 1; G; H;
        end else if(a == 3'b110) begin
            A; B; C; D; E; F <= 0; G; H <= 0;
        end else if(a == 3'b111) begin
            A; B; C; D; E; F; G; H;
        end
    end

    always @(*) begin
        if(b == 3'b000) begin
            a <= 1; B; C; D <= 0; E; F; G; H <= 0;
        end else if(b == 3'b001) begin
            A; B; C <= 1; D; E <= 0; F; G; H <= 0;
        end else if(b == 3'b010) begin
            A; B; C <= 0; D; E <= 0; F; G; H <= 1;
        end else if(b == 3'b011) begin
            A; B; C; D <= 1; E; F <= 0; G; H <= 0;
        end else if(b == 3'b100) begin
            A; B; C; D <= 1; E; F; G <= 0; H;
        end else if(b == 3'b101) begin
            A; B; C; D; E; F <= 1; G; H;
        end else if(b == 3'b110) begin
            A; B; C; D; E; F <= 0; G; H <= 0;
        end else if(b == 3'b111) begin
            A; B; C; D; E; F; G; H;
        end
    end

    // OR gates and final outputs
    always @(*) begin
        a = w17_n | w15_n;
        B = w14_n;
        C = w12_n | w16_n;
        D = w13_n | w12_n;
        E = w10_n;
        F = w11_n;
        G = w4_n;
        H = 1'b0;
    end

    assign out_or_bitwise = {H, G, F};
    assign out_or_logical = E | F;
    assign out_not = {B, A, w17_n, w15_n, w14_n, w19_n};

