    // Now we need to connect q0, q1, q2, q3 to the outputs of the memory cells

    // q0 will be controlled by addr[0:1] == 2'b0 and the latching value
    if (addr[7:4] == 4'b0001) select_q0 = 1;
    else select_q0 = 0;

    always @(*) begin
        q0 = {select_q0, select_q0};
    end

    // q1 will be controlled by addr[0:1] == 2'b1 and the latching value
    if (addr[7:4] == 4'b0010) select_q1 = 1;
    else select_q1 = 0;

    always @(*) begin
        q1 = {select_q1, select_q1};
    end

    // q2 will be controlled by addr[0:1] == 2'b00 and the latching value
    if (addr[7:4] == 4'b1101) select_q2 = 1;
    else select_q2 = 0;

    always @(*) begin
        q2 = {select_q2[1], select_q2[0]};
    end

    // q3 will be controlled by addr[0:1] == 2'b11 and the latching value
    if (addr[7:4] == 4'b1111) select_q3 = 1;
    else select_q3 = 0;

    always @(*) begin
        q3 = {select_q3[1], select_q3[0]};
    end

module-combinational-gates (
    input wire [7:0] addr,      // 8-bit Address input
    output reg dout             // 16-bit Data output
);

    assign dout = (addr[7:4] == 4'b0001) ? 16'h0000 : (addr[7:4] == 4'b0010) ? 16'h0000 : (addr[7:4] == 4'b0101) ? 16'h0000 : (addr[7:4] == 4'b1001) ? 16'h0000 : 16'h0000;

