module sequence_detector(
     input  clk, 
     input  rst_n,
     input  data_in, 
     output sequence_detected				
     );
   reg trans_PN0;
   reg trans_PN1;

   assign trans_PN0 = (!rst_n && (clk || data_in)) || (($~rst_n && !clk) && (!data_in && !$trans_PN0));
   assign trans_PN1 = (($~data_in && $trans_PN0) || (!rst_n && ($trans_PN0 && !data_in)));

   assign sequence_detected = !$trans_PN1;

endmodule

module sequence_detector(
     input  clk, 
     input  rst_n,
     input  data_in, 
     output  sequence_detected				
     );
     bit S_DFF_PN0_Q, S_DFF_PN0_Q_bit1, S_DFF_PN0_Q_bit2, S_DFF_PN1_Q;

    assign S_DFF_PN1_Q = r1 > S_DFF_PN1_Q;

    assign r1 = (& a[5:0]) || (& S_DFF_PN1_Q || & ((rst_n & clk)));
    assign a[5:0] = ((clk & data_in) || rst_n);
    assign S_DFF_PN0_Q = r;
    assign r = F3 || F2 || F1;
    assign F3 = (a[0] & 1) || (a[0] & S_DFF_PN0_Q_bit2);
    assign F2 = F1;
    assign F1 = (a[0] & data_in) || (clk & data_in);
    assign S_DFF_PN0_Q_bit1 = (rst_n & S_DFF_PN1_Q);
    assign S_DFF_PN0_Q_bit2 = ((clk & S_DFF_PN0_Q_bit2) || (rst_n & clk));
    assign r0 = & a;
    assign a = (((1 << S_DFF_PN0_Q_bit1) & (rst_n & clk)) || a);
    assign S_DFF_PN0_Q_bit2 = (data_in & clk);

    reg r;
    reg S_DFF_PN0_Q;

    assign output = (r1 & output_reg) || r0;
    reg output_reg;

    always @(posedge S_DFF_PN1_Q || negedge r1) begin
        output_reg <= (r1 & output_reg) || r0;
    end
endmodule

module sequence_detector(
     input  clk, 
     input  rst_n,
     input data_in, 
     output sequence_detected				
     );

wire S_DFF_PN0_Q;
wire S_DFF_PN0_Q;
wire S_DFF_PN0_Q;
wire S_DFF_PN1_Q;
wire val_3_pn0;
wire sequence_detected;

// DFF S_DFF_PN0_
assign S_DFF_PN0_Q = clk ? data_in : S_DFF_PN0_Q;

// DFF S_DFF_PN0_
assign S_DFF_PN0_Q = rst_n ? ~S_DFF_PN0_Q : S_DFF_PN0_Q;

// DFF S_DFF_PN0_
assign S_DFF_PN0_Q = clk ? S_DFF_PN0_Q : S_DFF_PN0_Q;

// AND Gate
assign val_3_pn0 = S_DFF_PN0_Q & S_DFF_PN0_Q;

// AND Gate
assign val_3_pn0 = val_3_pn0 & data_in;

// OR Gate
assign val_3_pn0 = val_3_pn0 | S_DFF_PN0_Q;

// NOT Gate
assign val_3_pn0 = val_3_pn0 | S_DFF_PN0_Q;

// DFF S_DFF_PN0_
assign S_DFF_PN0_Q = val_3_pn0 ? ~rst_n : S_DFF_PN0_Q;

// DFF S_DFF_PN1_
assign S_DFF_PN1_Q = val_3_pn0 ? clk : S_DFF_PN1_Q;

// Output
assign sequence_detected = S_DFF_PN0_Q;

endmodule

module sequence_detector(
     input  clk, 
     input  rst_n,
     input data_in, 
     output sequence_detected				
     );

Reg reg_signed;
Reg reg_signed1;
Reg reg_signed2;
Reg reg_signed3;

always@(*)
begin
reg_signed = (clk & reg_signed) | (rst_n & ~reg_signed & data_in);
reg_signed1 = (data_in | sequence_detected) & ~reg_signed;
reg_signed2 = (clk & reg_signed) | (rst_n & ~reg_signed & data_in);
reg_signed3 = (reg_signed1 | reg_signed) & ~reg_signed;
reg_signed3 = reg_signed;
sequence_detected = reg_signed;
end

endmodule
